#!/bin/bash
# Autogenerated deployment script for kyc-validator
set -e
cd "$(dirname "$0")"

echo "=== Building web client for kyc-validator ==="
cd web
npm install
npm run build
cd ..

echo "=== Deploying to Hostinger via rsync ==="
# Note: Ensure you have added 'hostinger-portfolio' to your SSH config.
# If using env vars: rsync -avz --delete web/dist/ $HOSTINGER_USER@$HOSTINGER_HOST:/home/u918475266/public_html/kyc-validator/
rsync -avz --delete web/dist/ hostinger-portfolio:/home/u918475266/public_html/kyc-validator/

echo "=== Deployment for kyc-validator completed successfully ==="
